 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
 */
function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
  switch (coupon.kind) {
    case "PERCENT":
      return Math.round((baseCents * coupon.value) / 100);
    case "FIXED_CENTS":
    case "CREDIT_CENTS":
      return coupon.value;
    default:
      return 0;
  }
