// Typed access layer over the key/value `Setting` store (db.setting).
//
// Plain (non-"use server") module so it can export the SETTINGS_DEFAULTS map,
// types and pure helpers alongside the async DB getters/setters. Import it from
// server components, server actions and the worker. Do NOT import from client
// components.
//
// Every admin-editable knob lives here with a default, so reads are total: a key
// that has never been written falls back to its SETTINGS_DEFAULTS value. Booleans
// are stored as the strings "true"/"false"; money is stored in cents; percents as
// plain numbers (e.g. "8.5" = 8.5%).

import { db } from "./db";

export const SETTINGS_DEFAULTS = {
  // --- General / Branding ---
  brand_name: "Nxeon",
  brand_tagline: "Premium VPS hosting, provisioned in seconds.",
  support_email: "",
  company_legal_name: "",
  company_address: "",
  social_twitter: "",
  social_github: "",
  social_discord: "",
  social_linkedin: "",
  footer_text: "",

  // --- Billing ---
  currency: "USD",
  tax_percent: "0",
  min_topup_cents: "500",
  default_term: "monthly",
  invoice_prefix: "INV-",
  dunning_grace_days: "3",
  dunning_warn_days: "7",
  dunning_terminate_days: "14",
  auto_suspend_enabled: "true",

  // --- Domains ---
  domain_markup_percent: "0",
  whois_privacy_default: "true",

  // --- Dedicated IP ---
  dedicated_ip_price_cents: "300",
  dedicated_ip_replenish_threshold: "3",

  // --- Provisioning & limits ---
  default_plan_slug: "",
  max_servers_per_user: "10",
  signup_free_credit_cents: "0",
  maintenance_mode: "false",
  maintenance_message: "We're performing scheduled maintenance and will be back shortly.",

  // --- Growth ---
  referral_reward_cents: "500",
  coupons_enabled: "true",

  // --- Email / SMTP --- (keys mirror lib/mailer.ts)
  smtp_host: "",
  smtp_port: "587",
  smtp_user: "",
  smtp_pass: "",
  smtp_from: "",
  smtp_secure: "false",

  // --- Security ---
  enforce_staff_2fa: "false",
  session_length_days: "30",
  login_ratelimit_max: "10",
  allowed_admin_ips: "",

  // --- Feature flags ---
  feature_game_servers: "true",
  feature_claude_builder: "true",
  feature_domains: "true",
  feature_newsletter: "true",
  feature_referrals: "true",
} as const;

export type SettingKey = keyof typeof SETTINGS_DEFAULTS;

/** Keys whose stored value is a secret — never rendered back to the browser. */
export const SECRET_KEYS: readonly string[] = ["smtp_pass"] as const;

/** True-ish coercion for values stored as "true"/"false"/"on"/"1". */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

/** Read one setting, falling back to an explicit default then SETTINGS_DEFAULTS. */
export async function getSetting(key: SettingKey | string, fallback?: string): Promise<string> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return row.value;
  return fallback ?? SETTINGS_DEFAULTS[key as SettingKey] ?? "";
}

/** Read one setting as a boolean. */
export async function getSettingBool(key: SettingKey | string, fallback = false): Promise<boolean> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return isTrue(row.value);
  const def = SETTINGS_DEFAULTS[key as SettingKey];
  return def !== undefined ? isTrue(def) : fallback;
}

/** Read one setting as an integer (cents, days, counts…). */
export async function getSettingInt(key: SettingKey | string, fallback = 0): Promise<number> {
  const raw = await getSetting(key, String(fallback));
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

/** Upsert one setting. */
export async function setSetting(key: SettingKey | string, value: string): Promise<void> {
  await db.setting.upsert({
    where: { key },
    update: { value },
    create: { key, value },
  });
}

/**
 * Every setting, with defaults merged under any stored overrides. Secret values
 * ARE included — callers that hand this to the client (the settings page) must
 * strip SECRET_KEYS themselves.
 */
export async function getAllSettings(): Promise<Record<string, string>> {
  const rows = await db.setting.findMany();
  const merged: Record<string, string> = { ...SETTINGS_DEFAULTS };
  for (const r of rows) merged[r.key] = r.value;
  return merged;
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { SETTINGS_DEFAULTS } from "./settings";

/**
 * Server actions for the admin settings hub. One entry point, `saveSettings`,
 * writes the rows for a single section (tab). Which keys belong to a section —
 * and how each is coerced — is described declaratively below so the action never
 * trusts the client for the key list.
 *
 * Coercion rules:
 *  - "bool":   checkbox → "true"/"false" (unchecked checkboxes don't POST, so we
 *              can't rely on presence alone; every bool key is always written).
 *  - "int":    trimmed, validated numeric; blank restores the default.
 *  - "secret": only written when non-blank, so a blank field never wipes the
 *              stored secret — and stored secrets are never echoed to the client.
 *  - "string": trimmed as-is.
 */

type FieldType = "string" | "bool" | "int" | "secret";
type Field = { key: string; type: FieldType };

const SECTION_FIELDS: Record<string, Field[]> = {
  general: [
    { key: "brand_name", type: "string" },
    { key: "brand_tagline", type: "string" },
    { key: "support_email", type: "string" },
    { key: "company_legal_name", type: "string" },
    { key: "company_address", type: "string" },
    { key: "social_twitter", type: "string" },
    { key: "social_github", type: "string" },
    { key: "social_discord", type: "string" },
    { key: "social_linkedin", type: "string" },
    { key: "footer_text", type: "string" },
  ],
  billing: [
    { key: "currency", type: "string" },
    { key: "tax_percent", type: "string" },
    { key: "min_topup_cents", type: "int" },
    { key: "default_term", type: "string" },
    { key: "invoice_prefix", type: "string" },
    { key: "dunning_grace_days", type: "int" },
    { key: "dunning_warn_days", type: "int" },
    { key: "dunning_terminate_days", type: "int" },
    { key: "auto_suspend_enabled", type: "bool" },
  ],
  domains: [
    { key: "domain_markup_percent", type: "string" },
    { key: "whois_privacy_default", type: "bool" },
  ],
  "dedicated-ip": [
    { key: "dedicated_ip_price_cents", type: "int" },
    { key: "dedicated_ip_replenish_threshold", type: "int" },
  ],
  provisioning: [
    { key: "default_plan_slug", type: "string" },
    { key: "max_servers_per_user", type: "int" },
    { key: "signup_free_credit_cents", type: "int" },
    { key: "maintenance_mode", type: "bool" },
    { key: "maintenance_message", type: "string" },
  ],
  growth: [
    { key: "referral_reward_cents", type: "int" },
    { key: "coupons_enabled", type: "bool" },
  ],
  email: [
    { key: "smtp_host", type: "string" },
    { key: "smtp_port", type: "int" },
    { key: "smtp_user", type: "string" },
    { key: "smtp_pass", type: "secret" },
    { key: "smtp_from", type: "string" },
    { key: "smtp_secure", type: "bool" },
  ],
  security: [
    { key: "enforce_staff_2fa", type: "bool" },
    { key: "session_length_days", type: "int" },
    { key: "login_ratelimit_max", type: "int" },
    { key: "allowed_admin_ips", type: "string" },
  ],
  features: [
    { key: "feature_game_servers", type: "bool" },
    { key: "feature_claude_builder", type: "bool" },
    { key: "feature_domains", type: "bool" },
    { key: "feature_newsletter", type: "bool" },
    { key: "feature_referrals", type: "bool" },
  ],
};

/** Sections that are billing-adjacent are gated on the "billing" area; the rest
 *  on "platform". BILLING-role staff may thus edit money-facing knobs. */
const BILLING_SECTIONS = new Set(["billing", "domains", "dedicated-ip"]);

type Result = { ok?: boolean; error?: string };

/**
 * Persist one section of settings. Bind the section server-side in the panel
 * (`saveSettings.bind(null, "general")`) so it's never client-supplied; React's
 * useActionState then supplies (prevState, formData).
 */
export async function saveSettings(
  section: string,
  _prev: Result | undefined,
  formData: FormData,
): Promise<Result> {
  const fields = SECTION_FIELDS[section];
  if (!fields) return { error: "Unknown settings section." };

  const area = BILLING_SECTIONS.has(section) ? "billing" : "platform";
  const user = await requireArea(area);

  const changes: { key: string; value: string }[] = [];

  for (const f of fields) {
    const raw = formData.get(f.key);

    if (f.type === "bool") {
      changes.push({ key: f.key, value: raw ? "true" : "false" });
      continue;
    }

    if (f.type === "secret") {
      const v = (raw ?? "").toString();
      if (v.trim() === "") continue; // never clear/overwrite a stored secret with blank
      changes.push({ key: f.key, value: v });
      continue;
    }

    if (f.type === "int") {
      const s = (raw ?? "").toString().trim();
      if (s === "") {
        changes.push({ key: f.key, value: SETTINGS_DEFAULTS[f.key as keyof typeof SETTINGS_DEFAULTS] ?? "0" });
        continue;
      }
      const n = Number(s);
      if (!Number.isFinite(n)) return { error: `“${f.key}” must be a number.` };
      changes.push({ key: f.key, value: String(Math.round(n)) });
      continue;
    }

    changes.push({ key: f.key, value: (raw ?? "").toString().trim() });
  }

  if (changes.length === 0) return { ok: true };

  await db.$transaction(
    changes.map((c) =>
      db.setting.upsert({ where: { key: c.key }, update: { value: c.value }, create: { key: c.key, value: c.value } }),
    ),
  );

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "settings.save",
      detail: `${section}: ${changes.map((c) => c.key).join(", ")}`,
    },
  });

  revalidatePath("/admin/settings");
  return { ok: true };
}

"use client";

import { useActionState } from "react";
import { saveSettings } from "@/lib/actions-settings";

type Result = { ok?: boolean; error?: string };

/**
 * Card-shaped settings form. Binds `saveSettings` to a fixed section server-side
 * and wires the shared save bar. Children are field components (below); pass
 * `wide` to a field to make it span both grid columns.
 */
export function SettingsForm({
  section,
  title,
  desc,
  children,
}: {
  section: string;
  title: string;
  desc?: string;
  children: React.ReactNode;
}) {
  const [state, action, pending] = useActionState<Result, FormData>(
    saveSettings.bind(null, section),
    {},
  );

  return (
    <form action={action} className="card space-y-6 p-6">
      <div>
        <h2 className="text-lg font-semibold">{title}</h2>
        {desc && <p className="mt-1 text-sm text-slate-400">{desc}</p>}
      </div>

      <div className="grid gap-5 sm:grid-cols-2">{children}</div>

      <div className="flex items-center gap-3 border-t border-white/[0.06] pt-5">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save changes"}
        </button>
        {!pending && state?.ok && <span className="text-sm text-emerald-400">Saved.</span>}
        {!pending && state?.error && <span className="text-sm text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}

function Wrap({ wide, children }: { wide?: boolean; children: React.ReactNode }) {
  return <div className={wide ? "sm:col-span-2" : ""}>{children}</div>;
}

function Hint({ hint }: { hint?: string }) {
  return hint ? <p className="mt-1 text-xs text-slate-500">{hint}</p> : null;
}

export function TextField({
  label,
  name,
  defaultValue,
  placeholder,
  type = "text",
  hint,
  wide,
  min,
  step,
}: {
  label: string;
  name: string;
  defaultValue?: string;
  placeholder?: string;
  type?: string;
  hint?: string;
  wide?: boolean;
  min?: number;
  step?: number | string;
}) {
  return (
    <Wrap wide={wide}>
      <label className="label" htmlFor={`s-${name}`}>
        {label}
      </label>
      <input
        id={`s-${name}`}
        className="input"
        name={name}
        type={type}
        defaultValue={defaultValue}
        placeholder={placeholder}
        min={min}
        step={step}
      />
      <Hint hint={hint} />
    </Wrap>
  );
}

/** Secret input: never receives the stored value. `isSet` only tweaks the copy. */
export function SecretField({
  label,
  name,
  isSet,
  hint,
  wide,
}: {
  label: string;
  name: string;
  isSet?: boolean;
  hint?: string;
  wide?: boolean;
}) {
  return (
    <Wrap wide={wide}>
      <label className="label" htmlFor={`s-${name}`}>
        {label}
      </label>
      <input
        id={`s-${name}`}
        className="input"
        name={name}
        type="password"
        autoComplete="new-password"
        placeholder={isSet ? "•••••••• (unchanged)" : "Not set"}
      />
      <Hint hint={hint ?? "Leave blank to keep the current value."} />
    </Wrap>
  );
}

export function TextAreaField({
  label,
  name,
  defaultValue,
  placeholder,
  rows = 3,
  hint,
}: {
  label: string;
  name: string;
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
  hint?: string;
}) {
  return (
    <Wrap wide>
      <label className="label" htmlFor={`s-${name}`}>
        {label}
      </label>
      <textarea
        id={`s-${name}`}
        className="input"
        name={name}
        rows={rows}
        defaultValue={defaultValue}
        placeholder={placeholder}
      />
      <Hint hint={hint} />
    </Wrap>
  );
}

export function SelectField({
  label,
  name,
  defaultValue,
  options,
  hint,
  wide,
}: {
  label: string;
  name: string;
  defaultValue?: string;
  options: { value: string; label: string }[];
  hint?: string;
  wide?: boolean;
}) {
  return (
    <Wrap wide={wide}>
      <label className="label" htmlFor={`s-${name}`}>
        {label}
      </label>
      <select id={`s-${name}`} className="input" name={name} defaultValue={defaultValue}>
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
      <Hint hint={hint} />
    </Wrap>
  );
}

/** Accessible switch. Renders as a full-width row with label + description. */
export function ToggleField({
  label,
  name,
  defaultChecked,
  hint,
}: {
  label: string;
  name: string;
  defaultChecked?: boolean;
  hint?: string;
}) {
  return (
    <label className="flex cursor-pointer items-center justify-between gap-4 rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3 sm:col-span-2">
      <span>
        <span className="text-sm font-medium text-slate-100">{label}</span>
        {hint && <span className="mt-0.5 block text-xs text-slate-500">{hint}</span>}
      </span>
      <span className="relative inline-flex shrink-0">
        <input type="checkbox" name={name} defaultChecked={defaultChecked} className="peer sr-only" />
        <span className="block h-6 w-11 rounded-full bg-white/10 transition-colors peer-checked:bg-brand-500" />
        <span className="pointer-events-none absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform peer-checked:translate-x-5" />
      </span>
    </label>
  );
}

"use client";

import { Children, useState } from "react";

/**
 * Client tab shell for the settings hub. The page renders every panel (server-
 * and client-side alike) as ordered children; this component only shows/hides
 * them, so all forms stay mounted (and keep their unsaved state) as you switch
 * tabs. Data is fetched once, server-side, in the page.
 *
 * Deep-links via `?tab=<id>`: `initial` seeds the active tab from the URL and
 * selecting a tab updates the query string without a navigation.
 */
export function SettingsTabs({
  tabs,
  initial,
  children,
}: {
  tabs: { id: string; label: string }[];
  initial?: string;
  children: React.ReactNode;
}) {
  const panels = Children.toArray(children);
  const first = tabs[0]?.id ?? "";
  const seed = initial && tabs.some((t) => t.id === initial) ? initial : first;
  const [active, setActive] = useState(seed);

  function select(id: string) {
    setActive(id);
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      url.searchParams.set("tab", id);
      window.history.replaceState(null, "", url.toString());
    }
  }

  return (
    <div className="space-y-6">
      <div
        role="tablist"
        aria-label="Settings sections"
        className="scrollbar-none flex gap-1 overflow-x-auto rounded-xl border border-white/[0.06] bg-white/[0.02] p-1"
      >
        {tabs.map((t) => {
          const on = t.id === active;
          return (
            <button
              key={t.id}
              type="button"
              role="tab"
              aria-selected={on}
              onClick={() => select(t.id)}
              className={`whitespace-nowrap rounded-lg px-3.5 py-2 text-sm font-medium transition-colors ${
                on
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      {tabs.map((t, i) => (
        <div key={t.id} role="tabpanel" hidden={t.id !== active}>
          {panels[i]}
        </div>
      ))}
    </div>
  );
}

"use client";

import { SettingsForm, TextField, TextAreaField } from "./fields";

