"use client";

import { SettingsForm, TextField, SelectField, ToggleField } from "./fields";

const CURRENCIES = ["USD", "EUR", "GBP", "CAD", "AUD"].map((c) => ({ value: c, label: c }));
const TERMS = [
  { value: "monthly", label: "Monthly" },
  { value: "quarterly", label: "Quarterly" },
  { value: "annual", label: "Annual" },
];

export function BillingPanel({ v }: { v: Record<string, string> }) {
  return (
    <SettingsForm
      section="billing"
      title="Billing"
      desc="Currency, tax, invoicing and the dunning schedule that governs overdue accounts."
    >
      <SelectField label="Currency" name="currency" defaultValue={v.currency} options={CURRENCIES} />
      <TextField label="Tax rate (%)" name="tax_percent" type="number" min={0} step="0.01" defaultValue={v.tax_percent} />
      <TextField label="Minimum top-up (cents)" name="min_topup_cents" type="number" min={0} defaultValue={v.min_topup_cents} hint="Smallest wallet top-up allowed." />
      <SelectField label="Default billing term" name="default_term" defaultValue={v.default_term} options={TERMS} />
      <TextField label="Invoice number prefix" name="invoice_prefix" defaultValue={v.invoice_prefix} placeholder="INV-" />
      <TextField label="Dunning grace (days)" name="dunning_grace_days" type="number" min={0} defaultValue={v.dunning_grace_days} hint="Days overdue before dunning starts." />
      <TextField label="Dunning warn (days)" name="dunning_warn_days" type="number" min={0} defaultValue={v.dunning_warn_days} hint="Days overdue for the final-warning email." />
      <TextField label="Dunning terminate (days)" name="dunning_terminate_days" type="number" min={0} defaultValue={v.dunning_terminate_days} hint="Days overdue before suspension/termination." />
      <ToggleField
        label="Auto-suspend overdue accounts"
        name="auto_suspend_enabled"
        defaultChecked={v.auto_suspend_enabled === "true"}
        hint="Let the billing sweep suspend servers once the terminate threshold is reached."
