import { EmailTemplateEditor } from "@/components/admin/EmailTemplateEditor";
import { SmtpForm } from "./SmtpForm";

/**
 * Email tab = SMTP transport form + the transactional email-template editor
 * (owned by another agent; imported and mounted here per the settings spec).
 *
 * Server component so the editor renders in a server context regardless of
 * whether it is itself a server or client component. If EmailTemplateEditor
 * requires props, wire them here at integration time.
 */
export function EmailPanel({ v, hasPass }: { v: Record<string, string>; hasPass: boolean }) {
  return (
    <div className="space-y-6">
