}

import type { Role } from "@prisma/client";
import { AREA_ROLES } from "@/lib/rbac";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { StaffRoleControls } from "@/components/admin/StaffRoleControls";

/**
 * Staff & roles tab — mirrors the standalone /admin/staff page (same query, same
 * StaffRoleControls props) so the manager can live inside the settings hub. Data
 * is fetched by the settings page and passed in.
 */

export type StaffUser = {
  id: string;
  name: string;
  email: string;
  role: Role;
  createdAt: Date;
  suspended: boolean;
};

const roleTone: Record<string, "brand" | "green" | "amber" | "slate"> = {
  ADMIN: "brand",
  SUPPORT: "green",
  BILLING: "amber",
  CUSTOMER: "slate",
};

const roleBlurb: Record<string, string> = {
  ADMIN: "Full access to every area, including fleet, billing and platform settings.",
  SUPPORT: "Overview, the support desk and read-only client lookup.",
  BILLING: "Overview plus the whole revenue section — billing, invoices, subscriptions and plans.",
  CUSTOMER: "No access to the ops portal.",
};

export function StaffPanel({ users, meId }: { users: StaffUser[]; meId: string }) {
  const staff = users.filter((u) => u.role !== "CUSTOMER");
  const customers = users.filter((u) => u.role === "CUSTOMER");

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-lg font-semibold">Staff & roles</h2>
        <p className="mt-1 text-sm text-slate-400">
          {staff.length} staff member{staff.length === 1 ? "" : "s"} · {customers.length} customer
          {customers.length === 1 ? "" : "s"}
        </p>
      </div>

      {/* Role legend */}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        {(["ADMIN", "BILLING", "SUPPORT", "CUSTOMER"] as const).map((r) => (
          <div key={r} className="card p-4">
            <Badge tone={roleTone[r]}>{r.toLowerCase()}</Badge>
            <p className="mt-2 text-xs leading-relaxed text-slate-400">{roleBlurb[r]}</p>
            <p className="mt-2 text-[11px] text-slate-600">
              Areas:{" "}
              {Object.entries(AREA_ROLES)
                .filter(([, roles]) => r === "ADMIN" || roles.includes(r))
                .map(([a]) => a)
                .join(", ") || "none"}
            </p>
          </div>
        ))}
      </div>

      {/* Staff table */}
      <div>
        <h3 className="section-label mb-2">Staff</h3>
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Member</th>
                <th>Role</th>
                <th>Joined</th>
                <th className="text-right">Change role</th>
              </tr>
            </thead>
            <tbody>
              {staff.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-10 text-center text-slate-500">
                    No staff yet — promote a customer below to grant ops access.
                  </td>
                </tr>
              )}
              {staff.map((u) => (
                <tr key={u.id}>
                  <td>
                    <span className="font-medium">{u.name}</span>
                    <span className="ml-2 text-xs text-slate-500">{u.email}</span>
                    {u.suspended && (
                      <span className="ml-2">
                        <Badge tone="red">suspended</Badge>
                      </span>
                    )}
                  </td>
                  <td>
                    <Badge tone={roleTone[u.role]}>{u.role.toLowerCase()}</Badge>
                  </td>
                  <td className="text-xs text-slate-400">{timeAgo(u.createdAt)}</td>
                  <td>
                    <StaffRoleControls userId={u.id} role={u.role} isSelf={u.id === meId} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Customers — promote to staff */}
      <div>
        <h3 className="section-label mb-2">Customers</h3>
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Client</th>
                <th>Role</th>
                <th>Joined</th>
                <th className="text-right">Promote</th>
              </tr>
            </thead>
            <tbody>
              {customers.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-10 text-center text-slate-500">
                    No customer accounts.
                  </td>
                </tr>
              )}
              {customers.map((u) => (
                <tr key={u.id}>
                  <td>
                    <span className="font-medium">{u.name}</span>
                    <span className="ml-2 text-xs text-slate-500">{u.email}</span>
                  </td>
                  <td>
                    <Badge tone="slate">customer</Badge>
                  </td>
                  <td className="text-xs text-slate-400">{timeAgo(u.createdAt)}</td>
                  <td>
                    <StaffRoleControls userId={u.id} role={u.role} isSelf={u.id === meId} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <p className="text-xs text-slate-500">
        Role changes take effect immediately and are recorded in the audit log. You can&apos;t change your own role,
        and demoting the last admin should be avoided — keep at least one ADMIN account.
      </p>
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { getAllSettings, SECRET_KEYS } from "@/lib/settings";
import { PageHeader } from "@/components/ui/primitives";
import { SettingsTabs } from "@/components/admin/SettingsTabs";
import { GeneralPanel } from "@/components/admin/settings/GeneralPanel";
import { BillingPanel } from "@/components/admin/settings/BillingPanel";
import { DomainsPanel } from "@/components/admin/settings/DomainsPanel";
import { DedicatedIpPanel } from "@/components/admin/settings/DedicatedIpPanel";
import { ProvisioningPanel } from "@/components/admin/settings/ProvisioningPanel";
import { GrowthPanel } from "@/components/admin/settings/GrowthPanel";
import { EmailPanel } from "@/components/admin/settings/EmailPanel";
import { SecurityPanel } from "@/components/admin/settings/SecurityPanel";
import { FeatureFlagsPanel } from "@/components/admin/settings/FeatureFlagsPanel";
import { StaffPanel } from "@/components/admin/settings/StaffPanel";

export const dynamic = "force-dynamic";

const TABS = [
  { id: "general", label: "General & branding" },
  { id: "billing", label: "Billing" },
  { id: "domains", label: "Domains" },
  { id: "dedicated-ip", label: "Dedicated IP" },
  { id: "provisioning", label: "Provisioning" },
  { id: "growth", label: "Growth" },
  { id: "email", label: "Email & SMTP" },
  { id: "security", label: "Security" },
  { id: "features", label: "Feature flags" },
  { id: "staff", label: "Staff & roles" },
];

export default async function AdminSettings({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string }>;
}) {
  const me = await requireArea("platform");
  const { tab } = await searchParams;

  const [all, plans, users] = await Promise.all([
    getAllSettings(),
    db.plan.findMany({ orderBy: { sortOrder: "asc" }, select: { slug: true, name: true } }),
    db.user.findMany({
      orderBy: [{ role: "asc" }, { createdAt: "asc" }],
      select: { id: true, name: true, email: true, role: true, createdAt: true, suspended: true },
    }),
  ]);

  // Never hand secret values to the browser — panels get presence flags instead.
  const hasSmtpPass = Boolean(all.smtp_pass);
  const v: Record<string, string> = { ...all };
  for (const k of SECRET_KEYS) delete v[k];

  return (
    <div className="space-y-6">
      <PageHeader
        title="Platform settings"
        sub="Branding, billing, provisioning, security and every other customization knob — in one place."
      />

      <SettingsTabs tabs={TABS} initial={tab}>
        <GeneralPanel v={v} />
        <BillingPanel v={v} />
        <DomainsPanel v={v} />
        <DedicatedIpPanel v={v} />
        <ProvisioningPanel v={v} plans={plans} />
        <GrowthPanel v={v} />
        <EmailPanel v={v} hasPass={hasSmtpPass} />
        <SecurityPanel v={v} />
        <FeatureFlagsPanel v={v} />
        <StaffPanel users={users} meId={me.id} />
      </SettingsTabs>
    </div>
  );
}
